-- Compare refresh part 2/5 — choose_a/b=text(json), faq=jsonb

-- gemini-vs-chatgpt
UPDATE comparisons SET choose_a='["✅ You''re deep in Google Workspace — Gemini works natively inside Gmail, Docs, Sheets, and Slides", "✅ You want the best Google Search integration and real-time web information", "✅ You use Android or want the best mobile AI assistant for Google''s ecosystem", "✅ You need fast, affordable multimodal analysis of long documents with Gemini 3.5 Flash"]', choose_b='["✅ You need native image generation, advanced voice mode, or data analysis (code interpreter)", "✅ You want the largest third-party app ecosystem — ChatGPT connects to hundreds of apps", "✅ You want GPT-5.5''s flagship reasoning and broad benchmark performance", "✅ You build on the API — OpenAI''s developer ecosystem is the most mature"]', faq='[{"q": "Is Gemini better than ChatGPT in 2026?", "a": "On Google Workspace tasks, Gemini is the better choice thanks to native Gmail, Docs, and Sheets integration. On general benchmarks, GPT-5.5 and Gemini 3.5 Flash are competitive. ChatGPT offers more built-in features (image generation, voice, code interpreter) and a larger third-party ecosystem. Gemini wins for Google users; ChatGPT wins for general and developer use."}, {"q": "Is Gemini free?", "a": "Yes. Gemini has a capable free tier powered by Gemini 3.5 Flash. Paid plans add higher limits and deeper features: Google AI Plus is $7.99/month, AI Pro is $19.99/month with full Google Workspace integration, and AI Ultra is $99.99/month for the highest limits and priority access."}, {"q": "Can Gemini generate images?", "a": "Yes. Gemini generates images using Google''s Imagen model directly in the chat. Quality is strong for quick, in-context image creation, and it''s especially convenient if you already work inside the Google ecosystem."}, {"q": "What is the difference between Gemini and Google Bard?", "a": "Bard was Google''s original AI chatbot, rebranded as Gemini in February 2024. They are the same product line — if you used Bard, you''re now using Gemini. The rebrand came with major upgrades in model capabilities, now on Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вы активно работаете в Google Workspace — Gemini встроен прямо в Gmail, Документы, Таблицы и Презентации", "✅ Вам нужна лучшая интеграция с Google Поиском и актуальная информация из интернета", "✅ Вы используете Android или хотите лучший мобильный ИИ-ассистент для экосистемы Google", "✅ Вам нужен быстрый и доступный мультимодальный анализ длинных документов на Gemini 3.5 Flash"]', choose_b='["✅ Вам нужна встроенная генерация изображений, продвинутый голосовой режим или анализ данных (интерпретатор кода)", "✅ Вам нужна крупнейшая экосистема сторонних приложений — ChatGPT подключается к сотням сервисов", "✅ Вам важны флагманские рассуждения GPT-5.5 и высокие результаты в бенчмарках", "✅ Вы разрабатываете на API — экосистема разработчиков OpenAI самая зрелая"]', faq='[{"q": "Gemini лучше ChatGPT в 2026 году?", "a": "В задачах Google Workspace Gemini выигрывает благодаря встроенной интеграции с Gmail, Документами и Таблицами. В общих бенчмарках GPT-5.5 и Gemini 3.5 Flash конкурируют на равных. У ChatGPT больше встроенных возможностей (генерация изображений, голос, интерпретатор кода) и крупнее экосистема сторонних приложений. Gemini — выбор для пользователей Google, ChatGPT — для общих и разработческих задач."}, {"q": "Gemini бесплатный?", "a": "Да. У Gemini есть полноценный бесплатный тариф на базе Gemini 3.5 Flash. Платные планы дают более высокие лимиты и функции: Google AI Plus — $7.99/мес, AI Pro — $19.99/мес с полной интеграцией Google Workspace, AI Ultra — $99.99/мес с максимальными лимитами и приоритетным доступом."}, {"q": "Может ли Gemini создавать изображения?", "a": "Да. Gemini генерирует изображения с помощью модели Google Imagen прямо в чате. Качество хорошее для быстрого создания картинок в контексте, и это особенно удобно, если вы уже работаете в экосистеме Google."}, {"q": "В чём разница между Gemini и Google Bard?", "a": "Bard был первым ИИ-чатботом Google, переименованным в Gemini в феврале 2024 года. Это одна и та же линейка продуктов — если вы пользовались Bard, теперь вы используете Gemini. Переименование сопровождалось крупными улучшениями модели, сейчас это Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Trabajas a fondo con Google Workspace — Gemini funciona de forma nativa en Gmail, Docs, Sheets y Slides", "✅ Quieres la mejor integración con Google Search e información web en tiempo real", "✅ Usas Android o quieres el mejor asistente de IA móvil para el ecosistema de Google", "✅ Necesitas análisis multimodal rápido y asequible de documentos largos con Gemini 3.5 Flash"]', choose_b='["✅ Necesitas generación de imágenes nativa, modo de voz avanzado o análisis de datos (intérprete de código)", "✅ Quieres el mayor ecosistema de apps de terceros — ChatGPT se conecta con cientos de aplicaciones", "✅ Quieres el razonamiento insignia de GPT-5.5 y un amplio rendimiento en benchmarks", "✅ Desarrollas sobre la API — el ecosistema para desarrolladores de OpenAI es el más maduro"]', faq='[{"q": "¿Es Gemini mejor que ChatGPT en 2026?", "a": "En tareas de Google Workspace, Gemini es la mejor opción gracias a su integración nativa con Gmail, Docs y Sheets. En benchmarks generales, GPT-5.5 y Gemini 3.5 Flash están a la par. ChatGPT ofrece más funciones integradas (generación de imágenes, voz, intérprete de código) y un ecosistema de terceros más grande. Gemini gana para usuarios de Google; ChatGPT gana para uso general y de desarrollo."}, {"q": "¿Es Gemini gratis?", "a": "Sí. Gemini tiene un plan gratuito capaz impulsado por Gemini 3.5 Flash. Los planes de pago añaden límites más altos y más funciones: Google AI Plus cuesta $7.99/mes, AI Pro cuesta $19.99/mes con integración completa de Google Workspace, y AI Ultra cuesta $99.99/mes con los límites más altos y acceso prioritario."}, {"q": "¿Puede Gemini generar imágenes?", "a": "Sí. Gemini genera imágenes con el modelo Imagen de Google directamente en el chat. La calidad es sólida para crear imágenes rápidas en contexto y resulta especialmente cómodo si ya trabajas dentro del ecosistema de Google."}, {"q": "¿Cuál es la diferencia entre Gemini y Google Bard?", "a": "Bard fue el chatbot de IA original de Google, renombrado como Gemini en febrero de 2024. Son la misma línea de producto — si usabas Bard, ahora usas Gemini. El cambio de nombre vino con grandes mejoras en las capacidades del modelo, ahora sobre Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du arbeitest intensiv mit Google Workspace — Gemini läuft nativ in Gmail, Docs, Sheets und Slides", "✅ Du willst die beste Google-Search-Integration und Echtzeit-Webinformationen", "✅ Du nutzt Android oder willst den besten mobilen KI-Assistenten für Googles Ökosystem", "✅ Du brauchst schnelle, günstige multimodale Analyse langer Dokumente mit Gemini 3.5 Flash"]', choose_b='["✅ Du brauchst native Bildgenerierung, erweiterten Sprachmodus oder Datenanalyse (Code-Interpreter)", "✅ Du willst das größte Drittanbieter-Ökosystem — ChatGPT verbindet sich mit Hunderten von Apps", "✅ Du willst das Flaggschiff-Reasoning von GPT-5.5 und breite Benchmark-Leistung", "✅ Du entwickelst auf der API — das Entwickler-Ökosystem von OpenAI ist am ausgereiftesten"]', faq='[{"q": "Ist Gemini 2026 besser als ChatGPT?", "a": "Bei Google-Workspace-Aufgaben ist Gemini dank nativer Integration in Gmail, Docs und Sheets die bessere Wahl. In allgemeinen Benchmarks sind GPT-5.5 und Gemini 3.5 Flash gleichauf. ChatGPT bietet mehr integrierte Funktionen (Bildgenerierung, Sprache, Code-Interpreter) und ein größeres Drittanbieter-Ökosystem. Gemini gewinnt für Google-Nutzer, ChatGPT für allgemeine und Entwickleraufgaben."}, {"q": "Ist Gemini kostenlos?", "a": "Ja. Gemini hat eine leistungsfähige kostenlose Stufe mit Gemini 3.5 Flash. Bezahlpläne bieten höhere Limits und mehr Funktionen: Google AI Plus kostet 7,99 $/Monat, AI Pro 19,99 $/Monat mit voller Google-Workspace-Integration und AI Ultra 99,99 $/Monat mit den höchsten Limits und priorisiertem Zugang."}, {"q": "Kann Gemini Bilder generieren?", "a": "Ja. Gemini erstellt Bilder mit Googles Imagen-Modell direkt im Chat. Die Qualität ist gut für schnelle, kontextbezogene Bilderstellung und besonders praktisch, wenn du ohnehin im Google-Ökosystem arbeitest."}, {"q": "Was ist der Unterschied zwischen Gemini und Google Bard?", "a": "Bard war Googles ursprünglicher KI-Chatbot, der im Februar 2024 in Gemini umbenannt wurde. Es ist dieselbe Produktlinie — wenn du Bard genutzt hast, nutzt du jetzt Gemini. Die Umbenennung ging mit großen Verbesserungen der Modellfähigkeiten einher, heute auf Basis von Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Ви активно працюєте в Google Workspace — Gemini вбудований прямо в Gmail, Документи, Таблиці та Презентації", "✅ Вам потрібна найкраща інтеграція з Google Пошуком і актуальна інформація з інтернету", "✅ Ви користуєтеся Android або хочете найкращий мобільний ШІ-асистент для екосистеми Google", "✅ Вам потрібен швидкий і доступний мультимодальний аналіз довгих документів на Gemini 3.5 Flash"]', choose_b='["✅ Вам потрібна вбудована генерація зображень, розширений голосовий режим або аналіз даних (інтерпретатор коду)", "✅ Вам потрібна найбільша екосистема сторонніх додатків — ChatGPT підключається до сотень сервісів", "✅ Вам важливі флагманські міркування GPT-5.5 і високі результати в бенчмарках", "✅ Ви розробляєте на API — екосистема розробників OpenAI найзріліша"]', faq='[{"q": "Чи Gemini кращий за ChatGPT у 2026 році?", "a": "У задачах Google Workspace Gemini виграє завдяки вбудованій інтеграції з Gmail, Документами й Таблицями. У загальних бенчмарках GPT-5.5 і Gemini 3.5 Flash конкурують на рівних. ChatGPT має більше вбудованих можливостей (генерація зображень, голос, інтерпретатор коду) і більшу екосистему сторонніх додатків. Gemini — вибір для користувачів Google, ChatGPT — для загальних і розробницьких задач."}, {"q": "Чи Gemini безкоштовний?", "a": "Так. У Gemini є повноцінний безкоштовний тариф на базі Gemini 3.5 Flash. Платні плани дають вищі ліміти й функції: Google AI Plus — $7.99/міс, AI Pro — $19.99/міс з повною інтеграцією Google Workspace, AI Ultra — $99.99/міс із максимальними лімітами та пріоритетним доступом."}, {"q": "Чи може Gemini створювати зображення?", "a": "Так. Gemini генерує зображення за допомогою моделі Google Imagen прямо в чаті. Якість добра для швидкого створення зображень у контексті, і це особливо зручно, якщо ви вже працюєте в екосистемі Google."}, {"q": "Яка різниця між Gemini і Google Bard?", "a": "Bard був першим ШІ-чатботом Google, перейменованим на Gemini у лютому 2024 року. Це та сама лінійка продуктів — якщо ви користувалися Bard, тепер ви використовуєте Gemini. Перейменування супроводжувалося значними покращеннями моделі, зараз це Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם עובדים לעומק ב-Google Workspace — Gemini פועל באופן מובנה בתוך Gmail, Docs, Sheets ו-Slides", "✅ אתם רוצים את האינטגרציה הטובה ביותר עם Google Search ומידע עדכני מהרשת בזמן אמת", "✅ אתם משתמשים ב-Android או רוצים את עוזר ה-AI הנייד הטוב ביותר לאקוסיסטם של Google", "✅ אתם צריכים ניתוח מולטימודלי מהיר וזול של מסמכים ארוכים עם Gemini 3.5 Flash"]', choose_b='["✅ אתם צריכים יצירת תמונות מובנית, מצב קול מתקדם או ניתוח נתונים (מפרש קוד)", "✅ אתם רוצים את אקוסיסטם היישומים החיצוני הגדול ביותר — ChatGPT מתחבר למאות אפליקציות", "✅ אתם רוצים את יכולת החשיבה המובילה של GPT-5.5 וביצועים רחבים במבחני ביצועים", "✅ אתם מפתחים על ה-API — אקוסיסטם המפתחים של OpenAI הוא הבשל ביותר"]', faq='[{"q": "האם Gemini טוב יותר מ-ChatGPT ב-2026?", "a": "במשימות Google Workspace, Gemini הוא הבחירה הטובה יותר בזכות האינטגרציה המובנית עם Gmail, Docs ו-Sheets. במבחני ביצועים כלליים, GPT-5.5 ו-Gemini 3.5 Flash מתחרים ראש בראש. ל-ChatGPT יש יותר יכולות מובנות (יצירת תמונות, קול, מפרש קוד) ואקוסיסטם חיצוני גדול יותר. Gemini מנצח עבור משתמשי Google, ו-ChatGPT מנצח לשימוש כללי ולמפתחים."}, {"q": "האם Gemini חינמי?", "a": "כן. ל-Gemini יש שכבה חינמית חזקה המבוססת על Gemini 3.5 Flash. תוכניות בתשלום מוסיפות מגבלות גבוהות יותר ותכונות: Google AI Plus עולה 7.99$ לחודש, AI Pro עולה 19.99$ לחודש עם אינטגרציה מלאה ל-Google Workspace, ו-AI Ultra עולה 99.99$ לחודש עם המגבלות הגבוהות ביותר וגישה מועדפת."}, {"q": "האם Gemini יכול ליצור תמונות?", "a": "כן. Gemini יוצר תמונות באמצעות מודל Imagen של Google ישירות בצ''אט. האיכות טובה ליצירת תמונות מהירה בהקשר, וזה נוח במיוחד אם אתם כבר עובדים בתוך האקוסיסטם של Google."}, {"q": "מה ההבדל בין Gemini ל-Google Bard?", "a": "Bard היה צ''אטבוט ה-AI המקורי של Google, ששמו שונה ל-Gemini בפברואר 2024. זו אותה שורת מוצרים — אם השתמשתם ב-Bard, אתם משתמשים כעת ב-Gemini. שינוי השם לווה בשדרוגים משמעותיים ביכולות המודל, כיום מבוסס על Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous êtes plongé dans Google Workspace — Gemini fonctionne nativement dans Gmail, Docs, Sheets et Slides", "✅ Vous voulez la meilleure intégration à Google Search et des informations web en temps réel", "✅ Vous utilisez Android ou voulez le meilleur assistant IA mobile pour l''écosystème de Google", "✅ Vous avez besoin d''une analyse multimodale rapide et abordable de longs documents avec Gemini 3.5 Flash"]', choose_b='["✅ Vous avez besoin de génération d''images native, d''un mode vocal avancé ou d''analyse de données (interpréteur de code)", "✅ Vous voulez le plus grand écosystème d''applications tierces — ChatGPT se connecte à des centaines d''applications", "✅ Vous voulez le raisonnement phare de GPT-5.5 et de larges performances aux benchmarks", "✅ Vous développez sur l''API — l''écosystème développeur d''OpenAI est le plus mature"]', faq='[{"q": "Gemini est-il meilleur que ChatGPT en 2026 ?", "a": "Pour les tâches Google Workspace, Gemini est le meilleur choix grâce à son intégration native dans Gmail, Docs et Sheets. Sur les benchmarks généraux, GPT-5.5 et Gemini 3.5 Flash sont au coude à coude. ChatGPT offre plus de fonctions intégrées (génération d''images, voix, interpréteur de code) et un écosystème tiers plus large. Gemini l''emporte pour les utilisateurs Google ; ChatGPT l''emporte pour l''usage général et le développement."}, {"q": "Gemini est-il gratuit ?", "a": "Oui. Gemini propose une offre gratuite performante propulsée par Gemini 3.5 Flash. Les offres payantes ajoutent des limites plus élevées et plus de fonctions : Google AI Plus coûte 7,99 $/mois, AI Pro coûte 19,99 $/mois avec intégration complète de Google Workspace, et AI Ultra coûte 99,99 $/mois avec les limites les plus élevées et un accès prioritaire."}, {"q": "Gemini peut-il générer des images ?", "a": "Oui. Gemini génère des images avec le modèle Imagen de Google directement dans le chat. La qualité est solide pour la création rapide d''images en contexte, et c''est particulièrement pratique si vous travaillez déjà dans l''écosystème Google."}, {"q": "Quelle est la différence entre Gemini et Google Bard ?", "a": "Bard était le chatbot IA original de Google, rebaptisé Gemini en février 2024. C''est la même gamme de produits — si vous utilisiez Bard, vous utilisez désormais Gemini. Le changement de nom s''est accompagné d''améliorations majeures des capacités du modèle, aujourd''hui basé sur Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você trabalha muito no Google Workspace — o Gemini funciona nativamente no Gmail, Docs, Sheets e Slides", "✅ Você quer a melhor integração com o Google Search e informações da web em tempo real", "✅ Você usa Android ou quer o melhor assistente de IA móvel para o ecossistema do Google", "✅ Você precisa de análise multimodal rápida e acessível de documentos longos com o Gemini 3.5 Flash"]', choose_b='["✅ Você precisa de geração de imagens nativa, modo de voz avançado ou análise de dados (interpretador de código)", "✅ Você quer o maior ecossistema de apps de terceiros — o ChatGPT se conecta a centenas de aplicativos", "✅ Você quer o raciocínio de ponta do GPT-5.5 e amplo desempenho em benchmarks", "✅ Você desenvolve na API — o ecossistema de desenvolvedores da OpenAI é o mais maduro"]', faq='[{"q": "O Gemini é melhor que o ChatGPT em 2026?", "a": "Em tarefas do Google Workspace, o Gemini é a melhor escolha graças à integração nativa com Gmail, Docs e Sheets. Em benchmarks gerais, GPT-5.5 e Gemini 3.5 Flash estão empatados. O ChatGPT oferece mais recursos integrados (geração de imagens, voz, interpretador de código) e um ecossistema de terceiros maior. O Gemini vence para usuários do Google; o ChatGPT vence para uso geral e de desenvolvimento."}, {"q": "O Gemini é gratuito?", "a": "Sim. O Gemini tem um plano gratuito robusto com o Gemini 3.5 Flash. Os planos pagos adicionam limites maiores e mais recursos: o Google AI Plus custa US$ 7,99/mês, o AI Pro custa US$ 19,99/mês com integração completa do Google Workspace, e o AI Ultra custa US$ 99,99/mês com os limites mais altos e acesso prioritário."}, {"q": "O Gemini pode gerar imagens?", "a": "Sim. O Gemini gera imagens usando o modelo Imagen do Google diretamente no chat. A qualidade é boa para criação rápida de imagens em contexto e é especialmente conveniente se você já trabalha dentro do ecossistema do Google."}, {"q": "Qual é a diferença entre o Gemini e o Google Bard?", "a": "O Bard foi o chatbot de IA original do Google, renomeado como Gemini em fevereiro de 2024. É a mesma linha de produtos — se você usava o Bard, agora usa o Gemini. A mudança de nome veio com grandes melhorias nas capacidades do modelo, hoje baseado no Gemini 3.5 Flash."}]'::jsonb WHERE slug='gemini-vs-chatgpt' AND lang='pt';

-- grok-vs-chatgpt
UPDATE comparisons SET choose_a='["✅ You''re active on X (Twitter) and want AI that understands real-time social media context", "✅ You want current news and trending topics without a knowledge cutoff", "✅ You want more candid, less filtered AI responses — Grok has fewer content restrictions", "✅ You''re already paying for X Premium and want AI included in your subscription", "✅ You need maximum reasoning power — Grok 4 Heavy offers a 256K context window for deep, long-form analysis"]', choose_b='["✅ You need image generation, voice conversations, or advanced data analysis in one place", "✅ You want the most reliable, feature-complete AI for professional work", "✅ You need a large plugin, connector, and integration ecosystem", "✅ You want the best-documented, most widely supported AI platform for building apps", "✅ You want a genuinely free tier plus affordable paid plans starting at $8/month"]', faq='[{"q": "What is Grok AI?", "a": "Grok is xAI''s AI assistant built into X (Twitter). It has real-time access to X posts and trending topics, making it unique for social media intelligence. The current model, Grok 4.3, is a frontier model competitive with GPT-5.5 on reasoning and STEM benchmarks."}, {"q": "Is Grok free?", "a": "Grok is included with X Premium ($8/month). For more capability, SuperGrok is $30/month and the top-tier Grok Heavy plan (with Grok 4 Heavy) is $300/month. There is no fully unlimited free version."}, {"q": "Is Grok 4.3 better than GPT-5.5?", "a": "Grok 4.3 is competitive with GPT-5.5 on reasoning and math, and leads on some STEM tasks, while Grok 4 Heavy adds a 256K context window. For general-purpose use, coding, and ecosystem features, GPT-5.5 still has advantages. Grok''s main differentiator is real-time X/Twitter access."}, {"q": "Does Grok generate images?", "a": "Yes. Grok includes Aurora, its native image generation model, and is more permissive with image content than most AI assistants. ChatGPT also generates images natively with GPT-5.5, alongside voice and data analysis."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вы активны в X (Twitter) и хотите ИИ, понимающий контекст соцсетей в реальном времени", "✅ Вам нужны свежие новости и актуальные темы без ограничения по дате знаний", "✅ Вы хотите более откровенные и менее отфильтрованные ответы — у Grok меньше ограничений контента", "✅ Вы уже платите за X Premium и хотите ИИ в составе подписки", "✅ Вам нужна максимальная мощность рассуждений — Grok 4 Heavy даёт контекст 256K для глубокого анализа"]', choose_b='["✅ Вам нужны генерация изображений, голосовые беседы и продвинутый анализ данных в одном месте", "✅ Вы хотите самый надёжный и функционально полный ИИ для профессиональной работы", "✅ Вам нужна большая экосистема плагинов, коннекторов и интеграций", "✅ Вам нужна лучше всего документированная и наиболее поддерживаемая платформа для разработки приложений", "✅ Вы хотите по-настоящему бесплатный тариф и доступные планы от $8/месяц"]', faq='[{"q": "Что такое Grok AI?", "a": "Grok — это ИИ-ассистент от xAI, встроенный в X (Twitter). У него есть доступ к постам X и трендам в реальном времени, что делает его уникальным для анализа соцсетей. Текущая модель Grok 4.3 конкурентоспособна с GPT-5.5 в задачах рассуждений и STEM."}, {"q": "Grok бесплатный?", "a": "Grok входит в X Premium ($8/месяц). Для большего функционала есть SuperGrok за $30/месяц, а топовый план Grok Heavy (с Grok 4 Heavy) стоит $300/месяц. Полностью безлимитной бесплатной версии нет."}, {"q": "Grok 4.3 лучше, чем GPT-5.5?", "a": "Grok 4.3 конкурентоспособен с GPT-5.5 в рассуждениях и математике и лидирует в некоторых STEM-задачах, а Grok 4 Heavy добавляет контекст 256K. По универсальности, кодингу и экосистеме GPT-5.5 всё же впереди. Главное отличие Grok — доступ к X/Twitter в реальном времени."}, {"q": "Grok генерирует изображения?", "a": "Да. В Grok встроена собственная модель генерации изображений Aurora, и она менее строга к контенту, чем большинство ассистентов. ChatGPT тоже генерирует изображения нативно на GPT-5.5, вместе с голосом и анализом данных."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Eres activo en X (Twitter) y quieres una IA que entienda el contexto de las redes sociales en tiempo real", "✅ Quieres noticias actuales y temas de tendencia sin límite de fecha de conocimiento", "✅ Quieres respuestas más directas y menos filtradas — Grok tiene menos restricciones de contenido", "✅ Ya pagas X Premium y quieres la IA incluida en tu suscripción", "✅ Necesitas la máxima potencia de razonamiento — Grok 4 Heavy ofrece una ventana de contexto de 256K para análisis profundo"]', choose_b='["✅ Necesitas generación de imágenes, conversaciones por voz y análisis de datos avanzado en un solo lugar", "✅ Quieres la IA más fiable y completa para el trabajo profesional", "✅ Necesitas un gran ecosistema de plugins, conectores e integraciones", "✅ Quieres la plataforma de IA mejor documentada y más ampliamente compatible para crear aplicaciones", "✅ Quieres un nivel gratuito real y planes de pago asequibles desde $8/mes"]', faq='[{"q": "¿Qué es Grok AI?", "a": "Grok es el asistente de IA de xAI integrado en X (Twitter). Tiene acceso en tiempo real a las publicaciones de X y los temas de tendencia, lo que lo hace único para la inteligencia de redes sociales. El modelo actual, Grok 4.3, es competitivo con GPT-5.5 en razonamiento y pruebas STEM."}, {"q": "¿Grok es gratis?", "a": "Grok está incluido en X Premium ($8/mes). Para más capacidad, SuperGrok cuesta $30/mes y el plan superior Grok Heavy (con Grok 4 Heavy) cuesta $300/mes. No hay una versión totalmente ilimitada gratuita."}, {"q": "¿Grok 4.3 es mejor que GPT-5.5?", "a": "Grok 4.3 es competitivo con GPT-5.5 en razonamiento y matemáticas, y lidera en algunas tareas STEM, mientras que Grok 4 Heavy añade una ventana de contexto de 256K. Para uso general, programación y ecosistema, GPT-5.5 aún tiene ventajas. La principal diferencia de Grok es el acceso en tiempo real a X/Twitter."}, {"q": "¿Grok genera imágenes?", "a": "Sí. Grok incluye Aurora, su propio modelo de generación de imágenes, y es más permisivo con el contenido que la mayoría de asistentes. ChatGPT también genera imágenes de forma nativa con GPT-5.5, junto con voz y análisis de datos."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du bist aktiv auf X (Twitter) und willst eine KI, die den Kontext sozialer Medien in Echtzeit versteht", "✅ Du willst aktuelle Nachrichten und Trendthemen ohne Wissens-Stichtag", "✅ Du willst direktere, weniger gefilterte KI-Antworten — Grok hat weniger Inhaltsbeschränkungen", "✅ Du zahlst bereits für X Premium und willst die KI in deinem Abo enthalten haben", "✅ Du brauchst maximale Denkleistung — Grok 4 Heavy bietet ein 256K-Kontextfenster für tiefe Analysen"]', choose_b='["✅ Du brauchst Bildgenerierung, Sprachgespräche und fortgeschrittene Datenanalyse an einem Ort", "✅ Du willst die zuverlässigste, funktionsvollständigste KI für professionelle Arbeit", "✅ Du brauchst ein großes Ökosystem aus Plugins, Konnektoren und Integrationen", "✅ Du willst die am besten dokumentierte, am breitesten unterstützte KI-Plattform zum App-Bau", "✅ Du willst eine echte kostenlose Stufe plus erschwingliche Tarife ab $8/Monat"]', faq='[{"q": "Was ist Grok AI?", "a": "Grok ist der KI-Assistent von xAI, integriert in X (Twitter). Er hat Echtzeitzugriff auf X-Beiträge und Trendthemen, was ihn einzigartig für Social-Media-Intelligenz macht. Das aktuelle Modell Grok 4.3 ist bei Reasoning- und STEM-Benchmarks konkurrenzfähig mit GPT-5.5."}, {"q": "Ist Grok kostenlos?", "a": "Grok ist in X Premium ($8/Monat) enthalten. Für mehr Leistung kostet SuperGrok $30/Monat und der Top-Tarif Grok Heavy (mit Grok 4 Heavy) $300/Monat. Eine völlig unbegrenzte kostenlose Version gibt es nicht."}, {"q": "Ist Grok 4.3 besser als GPT-5.5?", "a": "Grok 4.3 ist bei Reasoning und Mathematik konkurrenzfähig mit GPT-5.5 und führt bei einigen STEM-Aufgaben, während Grok 4 Heavy ein 256K-Kontextfenster ergänzt. Für allgemeine Nutzung, Coding und Ökosystem hat GPT-5.5 noch Vorteile. Groks Hauptunterschied ist der Echtzeitzugriff auf X/Twitter."}, {"q": "Erzeugt Grok Bilder?", "a": "Ja. Grok enthält Aurora, sein eigenes Bildgenerierungsmodell, und ist bei Inhalten freizügiger als die meisten Assistenten. Auch ChatGPT erzeugt Bilder nativ mit GPT-5.5, zusammen mit Sprache und Datenanalyse."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Ви активні в X (Twitter) і хочете ШІ, який розуміє контекст соцмереж у реальному часі", "✅ Вам потрібні свіжі новини та актуальні теми без обмеження за датою знань", "✅ Ви хочете відвертіші й менш відфільтровані відповіді — у Grok менше обмежень контенту", "✅ Ви вже платите за X Premium і хочете ШІ у складі підписки", "✅ Вам потрібна максимальна потужність міркувань — Grok 4 Heavy дає контекст 256K для глибокого аналізу"]', choose_b='["✅ Вам потрібні генерація зображень, голосові розмови та розширений аналіз даних в одному місці", "✅ Ви хочете найнадійніший і функціонально найповніший ШІ для професійної роботи", "✅ Вам потрібна велика екосистема плагінів, конекторів та інтеграцій", "✅ Ви хочете найкраще задокументовану й найширше підтримувану платформу для розробки застосунків", "✅ Ви хочете справді безкоштовний тариф і доступні плани від $8/місяць"]', faq='[{"q": "Що таке Grok AI?", "a": "Grok — це ШІ-асистент від xAI, вбудований у X (Twitter). Він має доступ до дописів X і трендів у реальному часі, що робить його унікальним для аналізу соцмереж. Поточна модель Grok 4.3 конкурентна з GPT-5.5 у міркуваннях і STEM-тестах."}, {"q": "Grok безкоштовний?", "a": "Grok входить до X Premium ($8/місяць). Для більших можливостей є SuperGrok за $30/місяць, а топовий план Grok Heavy (з Grok 4 Heavy) коштує $300/місяць. Повністю безлімітної безкоштовної версії немає."}, {"q": "Grok 4.3 кращий за GPT-5.5?", "a": "Grok 4.3 конкурентний з GPT-5.5 у міркуваннях і математиці та лідирує в деяких STEM-завданнях, а Grok 4 Heavy додає контекст 256K. За універсальністю, кодингом та екосистемою GPT-5.5 усе ще попереду. Головна відмінність Grok — доступ до X/Twitter у реальному часі."}, {"q": "Grok генерує зображення?", "a": "Так. Grok має власну модель генерації зображень Aurora, і вона менш сувора до контенту, ніж більшість асистентів. ChatGPT також генерує зображення нативно на GPT-5.5, разом із голосом та аналізом даних."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם פעילים ב-X (טוויטר) ורוצים בינה מלאכותית שמבינה הקשר של רשתות חברתיות בזמן אמת", "✅ אתם רוצים חדשות עדכניות ונושאים חמים ללא מגבלת תאריך ידע", "✅ אתם רוצים תשובות ישירות ופחות מסוננות — ל-Grok יש פחות הגבלות תוכן", "✅ אתם כבר משלמים על X Premium ורוצים בינה מלאכותית כלולה במנוי", "✅ אתם צריכים עוצמת חשיבה מרבית — Grok 4 Heavy מציע חלון הקשר של 256K לניתוח מעמיק"]', choose_b='["✅ אתם צריכים יצירת תמונות, שיחות קוליות וניתוח נתונים מתקדם במקום אחד", "✅ אתם רוצים את הבינה המלאכותית האמינה והשלמה ביותר לעבודה מקצועית", "✅ אתם צריכים אקוסיסטם גדול של תוספים, מחברים ואינטגרציות", "✅ אתם רוצים את פלטפורמת הבינה המתועדת והנתמכת ביותר לבניית אפליקציות", "✅ אתם רוצים שכבה חינמית אמיתית ותוכניות בתשלום נגישות החל מ-$8 לחודש"]', faq='[{"q": "מה זה Grok AI?", "a": "Grok הוא עוזר הבינה המלאכותית של xAI המשולב ב-X (טוויטר). יש לו גישה בזמן אמת לפוסטים ב-X ולנושאים חמים, מה שהופך אותו ייחודי למודיעין רשתות חברתיות. המודל הנוכחי, Grok 4.3, תחרותי מול GPT-5.5 במבחני חשיבה ו-STEM."}, {"q": "האם Grok חינמי?", "a": "Grok כלול ב-X Premium ($8 לחודש). ליכולות נוספות, SuperGrok עולה $30 לחודש, והתוכנית העליונה Grok Heavy (עם Grok 4 Heavy) עולה $300 לחודש. אין גרסה חינמית בלתי מוגבלת לחלוטין."}, {"q": "האם Grok 4.3 טוב יותר מ-GPT-5.5?", "a": "Grok 4.3 תחרותי מול GPT-5.5 בחשיבה ובמתמטיקה ומוביל בחלק ממשימות ה-STEM, בעוד Grok 4 Heavy מוסיף חלון הקשר של 256K. לשימוש כללי, תכנות ואקוסיסטם ל-GPT-5.5 עדיין יש יתרונות. הבידול העיקרי של Grok הוא גישה בזמן אמת ל-X/טוויטר."}, {"q": "האם Grok יוצר תמונות?", "a": "כן. Grok כולל את Aurora, מודל יצירת התמונות שלו, והוא מתירני יותר לגבי תוכן מרוב העוזרים. גם ChatGPT יוצר תמונות באופן מובנה עם GPT-5.5, לצד קול וניתוח נתונים."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous êtes actif sur X (Twitter) et voulez une IA qui comprend le contexte des réseaux sociaux en temps réel", "✅ Vous voulez des actualités récentes et des sujets tendance sans date limite de connaissances", "✅ Vous voulez des réponses plus directes et moins filtrées — Grok a moins de restrictions de contenu", "✅ Vous payez déjà X Premium et voulez l''IA incluse dans votre abonnement", "✅ Vous avez besoin d''une puissance de raisonnement maximale — Grok 4 Heavy offre une fenêtre de contexte de 256K pour des analyses approfondies"]', choose_b='["✅ Vous avez besoin de génération d''images, de conversations vocales et d''analyse de données avancée au même endroit", "✅ Vous voulez l''IA la plus fiable et la plus complète pour le travail professionnel", "✅ Vous avez besoin d''un large écosystème de plugins, connecteurs et intégrations", "✅ Vous voulez la plateforme d''IA la mieux documentée et la plus largement prise en charge pour créer des applications", "✅ Vous voulez un vrai niveau gratuit plus des forfaits payants abordables à partir de $8/mois"]', faq='[{"q": "Qu''est-ce que Grok AI ?", "a": "Grok est l''assistant IA de xAI intégré à X (Twitter). Il a un accès en temps réel aux publications X et aux sujets tendance, ce qui le rend unique pour l''intelligence des réseaux sociaux. Le modèle actuel, Grok 4.3, est compétitif face à GPT-5.5 sur le raisonnement et les benchmarks STEM."}, {"q": "Grok est-il gratuit ?", "a": "Grok est inclus dans X Premium ($8/mois). Pour plus de capacités, SuperGrok coûte $30/mois et le forfait supérieur Grok Heavy (avec Grok 4 Heavy) coûte $300/mois. Il n''existe pas de version totalement illimitée gratuite."}, {"q": "Grok 4.3 est-il meilleur que GPT-5.5 ?", "a": "Grok 4.3 est compétitif face à GPT-5.5 sur le raisonnement et les maths, et il domine sur certaines tâches STEM, tandis que Grok 4 Heavy ajoute une fenêtre de contexte de 256K. Pour l''usage général, le codage et l''écosystème, GPT-5.5 conserve des avantages. Le principal atout de Grok est l''accès en temps réel à X/Twitter."}, {"q": "Grok génère-t-il des images ?", "a": "Oui. Grok inclut Aurora, son propre modèle de génération d''images, et il est plus permissif sur le contenu que la plupart des assistants. ChatGPT génère aussi des images nativement avec GPT-5.5, avec la voix et l''analyse de données."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você é ativo no X (Twitter) e quer uma IA que entenda o contexto das redes sociais em tempo real", "✅ Você quer notícias atuais e tópicos em alta sem limite de data de conhecimento", "✅ Você quer respostas mais diretas e menos filtradas — o Grok tem menos restrições de conteúdo", "✅ Você já paga pelo X Premium e quer a IA incluída na sua assinatura", "✅ Você precisa de máxima capacidade de raciocínio — o Grok 4 Heavy oferece janela de contexto de 256K para análises profundas"]', choose_b='["✅ Você precisa de geração de imagens, conversas por voz e análise de dados avançada em um só lugar", "✅ Você quer a IA mais confiável e completa para trabalho profissional", "✅ Você precisa de um grande ecossistema de plugins, conectores e integrações", "✅ Você quer a plataforma de IA mais bem documentada e amplamente suportada para criar aplicativos", "✅ Você quer um nível gratuito de verdade e planos pagos acessíveis a partir de $8/mês"]', faq='[{"q": "O que é o Grok AI?", "a": "Grok é o assistente de IA da xAI integrado ao X (Twitter). Ele tem acesso em tempo real às publicações do X e aos tópicos em alta, o que o torna único para inteligência de redes sociais. O modelo atual, Grok 4.3, é competitivo com o GPT-5.5 em raciocínio e benchmarks STEM."}, {"q": "O Grok é gratuito?", "a": "O Grok está incluído no X Premium ($8/mês). Para mais capacidade, o SuperGrok custa $30/mês e o plano superior Grok Heavy (com Grok 4 Heavy) custa $300/mês. Não há uma versão totalmente ilimitada gratuita."}, {"q": "O Grok 4.3 é melhor que o GPT-5.5?", "a": "O Grok 4.3 é competitivo com o GPT-5.5 em raciocínio e matemática e lidera em algumas tarefas STEM, enquanto o Grok 4 Heavy adiciona uma janela de contexto de 256K. Para uso geral, programação e ecossistema, o GPT-5.5 ainda tem vantagens. O principal diferencial do Grok é o acesso em tempo real ao X/Twitter."}, {"q": "O Grok gera imagens?", "a": "Sim. O Grok inclui o Aurora, seu próprio modelo de geração de imagens, e é mais permissivo com conteúdo do que a maioria dos assistentes. O ChatGPT também gera imagens nativamente com o GPT-5.5, além de voz e análise de dados."}]'::jsonb WHERE slug='grok-vs-chatgpt' AND lang='pt';

-- cline-vs-github-copilot
UPDATE comparisons SET choose_a='["✅ You want an autonomous AI agent inside VS Code that plans and executes multi-file tasks — creating files, running commands, and editing across your codebase", "✅ You want to bring your own API key (Claude Opus 4.8, GPT-5.5, Gemini 3.5) and keep full model flexibility with pay-per-use pricing", "✅ You work on complex refactoring where the AI needs to edit across many files in sequence", "✅ You prefer an open-source (Apache 2.0) tool with full transparency into every action the AI takes"]', choose_b='["✅ You want fast inline code completions as you type in VS Code, JetBrains, Visual Studio, or Neovim", "✅ Your team is on GitHub and needs AI woven into PRs, issues, and code review", "✅ You need enterprise features: SSO, audit logs, IP indemnity, and centralized policy controls", "✅ You want a predictable plan starting free ($0) or Pro at $10/mo rather than metered API bills"]', faq='[{"q": "What is Cline?", "a": "Cline is an open-source AI coding agent that runs inside VS Code. Unlike single-line completion tools, Cline can plan and execute complex multi-step tasks — creating files, running terminal commands, and making changes across your codebase autonomously."}, {"q": "Is Cline free?", "a": "The Cline extension is free and open-source (Apache 2.0). You pay only for the AI model API you connect it to — Claude, GPT-5.5, or Gemini token costs apply. Typical individual use runs about $5–50/month in API fees depending on your model and workload. Optional Teams ($20/mo, first 10 seats free) and Enterprise plans add collaboration and security features."}, {"q": "How much does GitHub Copilot cost in 2026?", "a": "Copilot Free is $0/mo (about 2,000 completions per month plus limited chat and agent use). Copilot Pro is $10/mo and Pro+ is $39/mo for individuals; verified students get Pro-level access free. For organizations, Copilot Business is $19/user/mo and Enterprise is $39/user/mo. All plans now include a monthly pool of GitHub AI Credits under usage-based billing."}, {"q": "Does GitHub Copilot work outside of GitHub?", "a": "Yes. Copilot works in VS Code, JetBrains, Neovim, and Visual Studio regardless of where your code is hosted. You need a GitHub account, but you don''t have to use GitHub for version control to benefit from Copilot''s suggestions."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам нужен автономный ИИ-агент внутри VS Code, который планирует и выполняет задачи по многим файлам — создаёт файлы, запускает команды и правит код по всему проекту", "✅ Вы хотите подключить собственный API-ключ (Claude Opus 4.8, GPT-5.5, Gemini 3.5) и сохранить полную свободу выбора модели с оплатой по факту использования", "✅ Вы занимаетесь сложным рефакторингом, где ИИ должен последовательно править множество файлов", "✅ Вы предпочитаете открытый инструмент (Apache 2.0) с полной прозрачностью каждого действия ИИ"]', choose_b='["✅ Вам нужны быстрые встроенные подсказки кода прямо при наборе в VS Code, JetBrains, Visual Studio или Neovim", "✅ Ваша команда работает на GitHub, и ИИ нужен внутри PR, issue и код-ревью", "✅ Вам важны корпоративные функции: SSO, журналы аудита, защита от патентных претензий (IP indemnity) и централизованные политики", "✅ Вам нужен предсказуемый тариф — бесплатный ($0) или Pro за $10/мес вместо счетов за токены API"]', faq='[{"q": "Что такое Cline?", "a": "Cline — это открытый ИИ-агент для написания кода, работающий внутри VS Code. В отличие от инструментов, дающих однострочные подсказки, Cline умеет планировать и выполнять сложные многошаговые задачи — создавать файлы, запускать команды в терминале и автономно вносить изменения по всему проекту."}, {"q": "Cline бесплатный?", "a": "Расширение Cline бесплатно и с открытым исходным кодом (Apache 2.0). Вы платите только за API модели, которую подключаете — за токены Claude, GPT-5.5 или Gemini. Обычно у одного разработчика уходит около $5–50 в месяц на API в зависимости от модели и нагрузки. Опциональные планы Teams ($20/мес, первые 10 мест бесплатно) и Enterprise добавляют совместную работу и безопасность."}, {"q": "Сколько стоит GitHub Copilot в 2026 году?", "a": "Copilot Free — $0/мес (около 2000 автодополнений в месяц плюс ограниченный чат и агент). Copilot Pro — $10/мес, Pro+ — $39/мес для частных пользователей; проверенные студенты получают доступ уровня Pro бесплатно. Для организаций Copilot Business стоит $19 за пользователя в месяц, Enterprise — $39. Все планы теперь включают ежемесячный пул кредитов GitHub AI Credits при биллинге по использованию."}, {"q": "Работает ли GitHub Copilot вне GitHub?", "a": "Да. Copilot работает в VS Code, JetBrains, Neovim и Visual Studio независимо от того, где размещён ваш код. Нужен аккаунт GitHub, но использовать GitHub для контроля версий необязательно, чтобы пользоваться подсказками Copilot."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Quieres un agente de IA autónomo dentro de VS Code que planifique y ejecute tareas en varios archivos — crear archivos, ejecutar comandos y editar en todo tu código", "✅ Quieres usar tu propia clave de API (Claude Opus 4.8, GPT-5.5, Gemini 3.5) y conservar total libertad de modelo con pago por uso", "✅ Trabajas en refactorizaciones complejas donde la IA debe editar muchos archivos en secuencia", "✅ Prefieres una herramienta de código abierto (Apache 2.0) con total transparencia sobre cada acción de la IA"]', choose_b='["✅ Quieres sugerencias de código en línea rápidas mientras escribes en VS Code, JetBrains, Visual Studio o Neovim", "✅ Tu equipo trabaja en GitHub y necesita IA integrada en PRs, issues y revisión de código", "✅ Necesitas funciones empresariales: SSO, registros de auditoría, indemnización de PI y controles de políticas centralizados", "✅ Quieres un plan predecible desde gratis ($0) o Pro a $10/mes en lugar de facturas variables de API"]', faq='[{"q": "¿Qué es Cline?", "a": "Cline es un agente de codificación con IA de código abierto que funciona dentro de VS Code. A diferencia de las herramientas de autocompletado de una sola línea, Cline puede planificar y ejecutar tareas complejas de varios pasos — crear archivos, ejecutar comandos de terminal y realizar cambios en todo tu código de forma autónoma."}, {"q": "¿Cline es gratis?", "a": "La extensión Cline es gratuita y de código abierto (Apache 2.0). Solo pagas la API del modelo que conectes — se aplican los costes por tokens de Claude, GPT-5.5 o Gemini. Un desarrollador individual suele gastar entre $5 y $50 al mes en API según el modelo y la carga. Los planes opcionales Teams ($20/mes, los primeros 10 puestos gratis) y Enterprise añaden colaboración y seguridad."}, {"q": "¿Cuánto cuesta GitHub Copilot en 2026?", "a": "Copilot Free cuesta $0/mes (unos 2000 autocompletados al mes más chat y agente limitados). Copilot Pro cuesta $10/mes y Pro+ $39/mes para particulares; los estudiantes verificados obtienen acceso nivel Pro gratis. Para organizaciones, Copilot Business cuesta $19 por usuario al mes y Enterprise $39. Todos los planes incluyen ahora un fondo mensual de GitHub AI Credits con facturación por uso."}, {"q": "¿Funciona GitHub Copilot fuera de GitHub?", "a": "Sí. Copilot funciona en VS Code, JetBrains, Neovim y Visual Studio sin importar dónde esté alojado tu código. Necesitas una cuenta de GitHub, pero no tienes que usar GitHub para el control de versiones para aprovechar las sugerencias de Copilot."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du willst einen autonomen KI-Agenten in VS Code, der Aufgaben über mehrere Dateien plant und ausführt — Dateien erstellt, Befehle ausführt und im gesamten Code Änderungen vornimmt", "✅ Du möchtest deinen eigenen API-Schlüssel (Claude Opus 4.8, GPT-5.5, Gemini 3.5) nutzen und volle Modellfreiheit mit nutzungsbasierter Abrechnung behalten", "✅ Du arbeitest an komplexem Refactoring, bei dem die KI viele Dateien nacheinander bearbeiten muss", "✅ Du bevorzugst ein Open-Source-Tool (Apache 2.0) mit voller Transparenz über jede Aktion der KI"]', choose_b='["✅ Du willst schnelle Inline-Codevorschläge beim Tippen in VS Code, JetBrains, Visual Studio oder Neovim", "✅ Dein Team arbeitet auf GitHub und braucht KI direkt in PRs, Issues und Code-Reviews", "✅ Du brauchst Enterprise-Funktionen: SSO, Audit-Logs, IP-Haftungsfreistellung und zentrale Richtliniensteuerung", "✅ Du willst einen planbaren Tarif ab kostenlos ($0) oder Pro für $10/Monat statt schwankender API-Rechnungen"]', faq='[{"q": "Was ist Cline?", "a": "Cline ist ein quelloffener KI-Coding-Agent, der in VS Code läuft. Anders als Tools mit einzeiliger Autovervollständigung kann Cline komplexe, mehrstufige Aufgaben planen und ausführen — Dateien erstellen, Terminalbefehle ausführen und autonom Änderungen im gesamten Code vornehmen."}, {"q": "Ist Cline kostenlos?", "a": "Die Cline-Erweiterung ist kostenlos und quelloffen (Apache 2.0). Du zahlst nur für die API des verbundenen Modells — es fallen Token-Kosten für Claude, GPT-5.5 oder Gemini an. Ein einzelner Entwickler gibt je nach Modell und Auslastung typischerweise etwa $5–50 pro Monat für die API aus. Optionale Teams- ($20/Monat, erste 10 Plätze gratis) und Enterprise-Pläne ergänzen Zusammenarbeit und Sicherheit."}, {"q": "Wie viel kostet GitHub Copilot 2026?", "a": "Copilot Free kostet $0/Monat (etwa 2.000 Vervollständigungen pro Monat plus eingeschränkte Chat- und Agent-Nutzung). Copilot Pro kostet $10/Monat und Pro+ $39/Monat für Einzelpersonen; verifizierte Studierende erhalten Pro-Zugang kostenlos. Für Organisationen kostet Copilot Business $19 pro Nutzer/Monat und Enterprise $39. Alle Pläne enthalten nun ein monatliches Kontingent an GitHub AI Credits bei nutzungsbasierter Abrechnung."}, {"q": "Funktioniert GitHub Copilot außerhalb von GitHub?", "a": "Ja. Copilot funktioniert in VS Code, JetBrains, Neovim und Visual Studio, unabhängig davon, wo dein Code gehostet ist. Du brauchst ein GitHub-Konto, musst GitHub aber nicht zur Versionsverwaltung nutzen, um von den Vorschlägen von Copilot zu profitieren."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам потрібен автономний ШІ-агент усередині VS Code, який планує та виконує задачі по багатьох файлах — створює файли, запускає команди й редагує код по всьому проєкту", "✅ Ви хочете підключити власний API-ключ (Claude Opus 4.8, GPT-5.5, Gemini 3.5) і зберегти повну свободу вибору моделі з оплатою за використання", "✅ Ви працюєте над складним рефакторингом, де ШІ має послідовно правити багато файлів", "✅ Ви віддаєте перевагу відкритому інструменту (Apache 2.0) з повною прозорістю кожної дії ШІ"]', choose_b='["✅ Вам потрібні швидкі вбудовані підказки коду просто під час набору у VS Code, JetBrains, Visual Studio чи Neovim", "✅ Ваша команда працює на GitHub, і ШІ потрібен усередині PR, issue та код-рев''ю", "✅ Вам важливі корпоративні функції: SSO, журнали аудиту, захист від патентних претензій (IP indemnity) і централізовані політики", "✅ Вам потрібен передбачуваний тариф — безкоштовний ($0) або Pro за $10/міс замість рахунків за токени API"]', faq='[{"q": "Що таке Cline?", "a": "Cline — це відкритий ШІ-агент для написання коду, що працює всередині VS Code. На відміну від інструментів з однорядковими підказками, Cline вміє планувати й виконувати складні багатокрокові задачі — створювати файли, запускати команди в терміналі та автономно вносити зміни по всьому проєкту."}, {"q": "Чи безкоштовний Cline?", "a": "Розширення Cline безкоштовне та з відкритим кодом (Apache 2.0). Ви платите лише за API моделі, яку підключаєте — за токени Claude, GPT-5.5 чи Gemini. Зазвичай один розробник витрачає близько $5–50 на місяць на API залежно від моделі та навантаження. Опціональні плани Teams ($20/міс, перші 10 місць безкоштовно) та Enterprise додають спільну роботу й безпеку."}, {"q": "Скільки коштує GitHub Copilot у 2026 році?", "a": "Copilot Free — $0/міс (близько 2000 автодоповнень на місяць плюс обмежені чат і агент). Copilot Pro — $10/міс, Pro+ — $39/міс для приватних користувачів; підтверджені студенти отримують доступ рівня Pro безкоштовно. Для організацій Copilot Business коштує $19 за користувача на місяць, Enterprise — $39. Усі плани тепер містять щомісячний пул кредитів GitHub AI Credits за біллінгом на основі використання."}, {"q": "Чи працює GitHub Copilot поза GitHub?", "a": "Так. Copilot працює у VS Code, JetBrains, Neovim та Visual Studio незалежно від того, де розміщено ваш код. Потрібен обліковий запис GitHub, але використовувати GitHub для контролю версій необов''язково, щоб користуватися підказками Copilot."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם רוצים סוכן AI אוטונומי בתוך VS Code שמתכנן ומבצע משימות על פני קבצים רבים — יוצר קבצים, מריץ פקודות ועורך קוד בכל הפרויקט", "✅ אתם רוצים לחבר מפתח API משלכם (Claude Opus 4.8, GPT-5.5, Gemini 3.5) ולשמור על גמישות מלאה בבחירת המודל עם תשלום לפי שימוש", "✅ אתם עובדים על ריפקטורינג מורכב שבו ה-AI צריך לערוך קבצים רבים ברצף", "✅ אתם מעדיפים כלי קוד פתוח (Apache 2.0) עם שקיפות מלאה לכל פעולה שה-AI מבצע"]', choose_b='["✅ אתם רוצים השלמות קוד מהירות תוך כדי הקלדה ב-VS Code, ב-JetBrains, ב-Visual Studio או ב-Neovim", "✅ הצוות שלכם עובד ב-GitHub וזקוק ל-AI משולב ב-PR, ב-issues ובביקורת קוד", "✅ אתם צריכים יכולות ארגוניות: SSO, יומני ביקורת, שיפוי קניין רוחני (IP indemnity) ובקרת מדיניות מרוכזת", "✅ אתם רוצים תוכנית צפויה — חינמית ($0) או Pro ב-$10 לחודש במקום חשבונות API משתנים"]', faq='[{"q": "מה זה Cline?", "a": "Cline הוא סוכן קוד מבוסס AI בקוד פתוח שרץ בתוך VS Code. בניגוד לכלים שמציעים השלמה של שורה בודדת, Cline יכול לתכנן ולבצע משימות מורכבות מרובות שלבים — ליצור קבצים, להריץ פקודות בטרמינל ולבצע שינויים בכל הקוד באופן אוטונומי."}, {"q": "האם Cline חינמי?", "a": "התוסף Cline הוא חינמי ובקוד פתוח (Apache 2.0). אתם משלמים רק על ה-API של המודל שאתם מחברים — עלויות טוקנים של Claude, GPT-5.5 או Gemini. מפתח יחיד מוציא בדרך כלל כ-$5–50 לחודש על API, בהתאם למודל ולעומס. תוכניות אופציונליות של Teams ($20 לחודש, 10 המושבים הראשונים בחינם) ו-Enterprise מוסיפות שיתוף פעולה ואבטחה."}, {"q": "כמה עולה GitHub Copilot ב-2026?", "a": "‏Copilot Free עולה $0 לחודש (כ-2,000 השלמות בחודש בתוספת צ''אט וסוכן מוגבלים). Copilot Pro עולה $10 לחודש ו-Pro+ עולה $39 לחודש לפרטיים; סטודנטים מאומתים מקבלים גישה ברמת Pro בחינם. לארגונים, Copilot Business עולה $19 למשתמש לחודש ו-Enterprise עולה $39. כל התוכניות כוללות כעת מאגר חודשי של GitHub AI Credits בחיוב לפי שימוש."}, {"q": "האם GitHub Copilot עובד מחוץ ל-GitHub?", "a": "כן. Copilot עובד ב-VS Code, ב-JetBrains, ב-Neovim וב-Visual Studio ללא קשר למקום שבו מאוחסן הקוד שלכם. דרוש חשבון GitHub, אך אינכם חייבים להשתמש ב-GitHub לניהול גרסאות כדי ליהנות מההצעות של Copilot."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous voulez un agent IA autonome dans VS Code qui planifie et exécute des tâches sur plusieurs fichiers — créer des fichiers, lancer des commandes et modifier tout votre code", "✅ Vous voulez utiliser votre propre clé API (Claude Opus 4.8, GPT-5.5, Gemini 3.5) et garder une liberté totale de modèle avec un paiement à l''usage", "✅ Vous travaillez sur des refactorisations complexes où l''IA doit modifier de nombreux fichiers en séquence", "✅ Vous préférez un outil open source (Apache 2.0) offrant une transparence totale sur chaque action de l''IA"]', choose_b='["✅ Vous voulez des suggestions de code en ligne rapides pendant la frappe dans VS Code, JetBrains, Visual Studio ou Neovim", "✅ Votre équipe est sur GitHub et a besoin d''une IA intégrée aux PR, aux issues et à la revue de code", "✅ Vous avez besoin de fonctionnalités d''entreprise : SSO, journaux d''audit, indemnisation de PI et contrôles de politiques centralisés", "✅ Vous voulez un forfait prévisible, gratuit ($0) ou Pro à $10/mois, plutôt que des factures API variables"]', faq='[{"q": "Qu''est-ce que Cline ?", "a": "Cline est un agent de codage IA open source qui s''exécute dans VS Code. Contrairement aux outils de complétion sur une seule ligne, Cline peut planifier et exécuter des tâches complexes en plusieurs étapes — créer des fichiers, lancer des commandes de terminal et modifier tout votre code de manière autonome."}, {"q": "Cline est-il gratuit ?", "a": "L''extension Cline est gratuite et open source (Apache 2.0). Vous ne payez que l''API du modèle que vous connectez — les coûts par token de Claude, GPT-5.5 ou Gemini s''appliquent. Un développeur individuel dépense généralement environ $5 à $50 par mois en API selon le modèle et la charge. Les forfaits optionnels Teams ($20/mois, les 10 premiers sièges gratuits) et Enterprise ajoutent collaboration et sécurité."}, {"q": "Combien coûte GitHub Copilot en 2026 ?", "a": "Copilot Free coûte $0/mois (environ 2 000 complétions par mois plus un chat et un agent limités). Copilot Pro coûte $10/mois et Pro+ $39/mois pour les particuliers ; les étudiants vérifiés obtiennent un accès niveau Pro gratuit. Pour les organisations, Copilot Business coûte $19 par utilisateur/mois et Enterprise $39. Tous les forfaits incluent désormais un pool mensuel de GitHub AI Credits avec une facturation à l''usage."}, {"q": "GitHub Copilot fonctionne-t-il en dehors de GitHub ?", "a": "Oui. Copilot fonctionne dans VS Code, JetBrains, Neovim et Visual Studio, quel que soit l''endroit où votre code est hébergé. Un compte GitHub est nécessaire, mais vous n''avez pas à utiliser GitHub pour le contrôle de version pour profiter des suggestions de Copilot."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você quer um agente de IA autônomo dentro do VS Code que planeja e executa tarefas em vários arquivos — criando arquivos, executando comandos e editando por todo o seu código", "✅ Você quer usar sua própria chave de API (Claude Opus 4.8, GPT-5.5, Gemini 3.5) e manter total flexibilidade de modelo com pagamento por uso", "✅ Você trabalha com refatorações complexas em que a IA precisa editar muitos arquivos em sequência", "✅ Você prefere uma ferramenta de código aberto (Apache 2.0) com total transparência sobre cada ação da IA"]', choose_b='["✅ Você quer sugestões de código embutidas e rápidas enquanto digita no VS Code, JetBrains, Visual Studio ou Neovim", "✅ Sua equipe está no GitHub e precisa de IA integrada a PRs, issues e revisão de código", "✅ Você precisa de recursos empresariais: SSO, logs de auditoria, indenização de PI e controles de política centralizados", "✅ Você quer um plano previsível, gratuito ($0) ou Pro por $10/mês, em vez de faturas variáveis de API"]', faq='[{"q": "O que é o Cline?", "a": "O Cline é um agente de codificação com IA de código aberto que roda dentro do VS Code. Ao contrário das ferramentas de autocompletar de uma única linha, o Cline consegue planejar e executar tarefas complexas de várias etapas — criar arquivos, executar comandos no terminal e fazer alterações em todo o seu código de forma autônoma."}, {"q": "O Cline é gratuito?", "a": "A extensão Cline é gratuita e de código aberto (Apache 2.0). Você paga apenas pela API do modelo que conectar — aplicam-se os custos por token do Claude, GPT-5.5 ou Gemini. Um desenvolvedor individual costuma gastar entre $5 e $50 por mês em API, dependendo do modelo e da carga. Os planos opcionais Teams ($20/mês, os primeiros 10 assentos grátis) e Enterprise adicionam colaboração e segurança."}, {"q": "Quanto custa o GitHub Copilot em 2026?", "a": "O Copilot Free custa $0/mês (cerca de 2.000 autocompletions por mês, além de chat e agente limitados). O Copilot Pro custa $10/mês e o Pro+ $39/mês para indivíduos; estudantes verificados ganham acesso nível Pro gratuitamente. Para organizações, o Copilot Business custa $19 por usuário/mês e o Enterprise $39. Todos os planos agora incluem um pool mensal de GitHub AI Credits com cobrança baseada em uso."}, {"q": "O GitHub Copilot funciona fora do GitHub?", "a": "Sim. O Copilot funciona no VS Code, JetBrains, Neovim e Visual Studio, independentemente de onde seu código está hospedado. É necessária uma conta GitHub, mas você não precisa usar o GitHub para controle de versão para aproveitar as sugestões do Copilot."}]'::jsonb WHERE slug='cline-vs-github-copilot' AND lang='pt';

-- consensus-vs-perplexity
UPDATE comparisons SET choose_a='["✅ You need answers backed by peer-reviewed scientific papers — not just web pages", "✅ You''re a researcher, student, or health professional who needs cited academic sources", "✅ You want consensus meters that show what percentage of studies agree on a claim", "✅ You work in medicine, science, or policy where evidence quality matters most", "✅ You want Deep Search across 200M+ papers at a low price — Pro is $10/mo, Student $9/mo"]', choose_b='["✅ You want fast answers from across the entire web, not just academic databases", "✅ You need current news, recent events, or information updated within days", "✅ You want agentic Deep Research powered by Claude Opus 4.5/4.6 (Pro and Max plans)", "✅ You want multi-model access — GPT-5, Claude, and Gemini in one search tool", "✅ You need a general-purpose AI search engine for everyday research questions"]', faq='[{"q": "What is Consensus AI?", "a": "Consensus is an AI-powered academic search engine that searches 200M+ peer-reviewed papers. Its Deep Search and Research Agent extract key findings, show consensus percentages across studies, and provide cited answers — specifically for scientific and medical questions."}, {"q": "Is Consensus free?", "a": "Yes. The free plan includes basic Quick Search, abstract summaries, limited Pro messages, and about 3 Deep Searches per month. Consensus Pro is $10/month, and students can get Pro for $9/month with .edu/.ac verification."}, {"q": "Is Perplexity good for academic research?", "a": "Perplexity searches the web including academic sources, but it doesn''t specialize in peer-reviewed papers the way Consensus does. For academic research requiring study citations and evidence quality, Consensus is more reliable. Perplexity is better for broad, current-events research and agentic Deep Research."}, {"q": "How much does Perplexity cost?", "a": "Perplexity Free is $0 with about 5 Pro searches per day. Perplexity Pro is $20/month or $200/year and includes around 20 Deep Research runs per day; Max is $200/month or $2,000/year. Deep Research runs on Claude Opus 4.5/4.6 for Pro and Max."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вам нужны ответы, подкреплённые рецензируемыми научными статьями, а не просто веб-страницами", "✅ Вы исследователь, студент или медицинский специалист, которому нужны цитируемые академические источники", "✅ Вам нужен индикатор консенсуса, показывающий, какой процент исследований согласен с утверждением", "✅ Вы работаете в медицине, науке или политике, где качество доказательств важнее всего", "✅ Вам нужен Deep Search по 200+ млн статей по низкой цене — Pro $10/мес, для студентов $9/мес"]', choose_b='["✅ Вам нужны быстрые ответы со всего интернета, а не только из академических баз", "✅ Вам нужны свежие новости, недавние события или информация, обновлённая за считанные дни", "✅ Вам нужен агентный Deep Research на базе Claude Opus 4.5/4.6 (планы Pro и Max)", "✅ Вам нужен доступ к нескольким моделям — GPT-5, Claude и Gemini в одном поисковом инструменте", "✅ Вам нужна универсальная ИИ-поисковая система для повседневных исследовательских вопросов"]', faq='[{"q": "Что такое Consensus AI?", "a": "Consensus — это академическая поисковая система на базе ИИ, которая ищет по более чем 200 млн рецензируемых статей. Deep Search и Research Agent извлекают ключевые выводы, показывают процент консенсуса между исследованиями и дают ответы со ссылками — специально для научных и медицинских вопросов."}, {"q": "Consensus бесплатный?", "a": "Да. Бесплатный план включает базовый Quick Search, краткие изложения аннотаций, ограниченное число Pro-сообщений и около 3 Deep Search в месяц. Consensus Pro стоит $10/мес, а студенты могут получить Pro за $9/мес с подтверждением .edu/.ac."}, {"q": "Подходит ли Perplexity для академических исследований?", "a": "Perplexity ищет по интернету, включая академические источники, но не специализируется на рецензируемых статьях так, как Consensus. Для академических исследований, требующих цитирования работ и оценки качества доказательств, Consensus надёжнее. Perplexity лучше подходит для широких исследований и свежих новостей."}, {"q": "Сколько стоит Perplexity?", "a": "Perplexity Free — $0 с примерно 5 Pro-поисками в день. Perplexity Pro стоит $20/мес или $200/год и включает около 20 запусков Deep Research в день; Max — $200/мес или $2000/год. Deep Research работает на Claude Opus 4.5/4.6 для планов Pro и Max."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Necesitas respuestas respaldadas por artículos científicos revisados por pares, no solo páginas web", "✅ Eres investigador, estudiante o profesional de la salud que necesita fuentes académicas citadas", "✅ Quieres medidores de consenso que muestren qué porcentaje de estudios coincide con una afirmación", "✅ Trabajas en medicina, ciencia o políticas públicas, donde la calidad de la evidencia importa más", "✅ Quieres Deep Search en más de 200 millones de artículos a bajo precio — Pro $10/mes, Estudiante $9/mes"]', choose_b='["✅ Quieres respuestas rápidas de toda la web, no solo de bases de datos académicas", "✅ Necesitas noticias actuales, eventos recientes o información actualizada en pocos días", "✅ Quieres Deep Research agéntico impulsado por Claude Opus 4.5/4.6 (planes Pro y Max)", "✅ Quieres acceso a varios modelos — GPT-5, Claude y Gemini en una sola herramienta de búsqueda", "✅ Necesitas un buscador de IA de propósito general para preguntas cotidianas de investigación"]', faq='[{"q": "¿Qué es Consensus AI?", "a": "Consensus es un buscador académico con IA que rastrea más de 200 millones de artículos revisados por pares. Su Deep Search y Research Agent extraen hallazgos clave, muestran porcentajes de consenso entre estudios y ofrecen respuestas con citas, específicamente para preguntas científicas y médicas."}, {"q": "¿Es gratis Consensus?", "a": "Sí. El plan gratuito incluye Quick Search básico, resúmenes de abstracts, mensajes Pro limitados y unas 3 Deep Searches al mes. Consensus Pro cuesta $10/mes, y los estudiantes pueden obtener Pro por $9/mes con verificación .edu/.ac."}, {"q": "¿Es Perplexity bueno para la investigación académica?", "a": "Perplexity busca en la web, incluidas fuentes académicas, pero no se especializa en artículos revisados por pares como lo hace Consensus. Para investigación académica que requiere citas de estudios y calidad de evidencia, Consensus es más fiable. Perplexity es mejor para investigación amplia y noticias de actualidad."}, {"q": "¿Cuánto cuesta Perplexity?", "a": "Perplexity Free es $0 con unas 5 búsquedas Pro al día. Perplexity Pro cuesta $20/mes o $200/año e incluye alrededor de 20 Deep Research al día; Max es $200/mes o $2000/año. Deep Research funciona con Claude Opus 4.5/4.6 en los planes Pro y Max."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du brauchst Antworten, die durch peer-reviewte wissenschaftliche Studien belegt sind — nicht nur durch Webseiten", "✅ Du bist Forscher, Student oder Gesundheitsfachkraft und brauchst zitierte akademische Quellen", "✅ Du willst Konsens-Anzeigen, die zeigen, wie viel Prozent der Studien einer Aussage zustimmen", "✅ Du arbeitest in Medizin, Wissenschaft oder Politik, wo Evidenzqualität am wichtigsten ist", "✅ Du willst Deep Search über 200+ Mio. Studien zum niedrigen Preis — Pro $10/Monat, Student $9/Monat"]', choose_b='["✅ Du willst schnelle Antworten aus dem gesamten Web, nicht nur aus akademischen Datenbanken", "✅ Du brauchst aktuelle Nachrichten, jüngste Ereignisse oder Informationen, die tagesaktuell sind", "✅ Du willst agentische Deep Research auf Basis von Claude Opus 4.5/4.6 (Pro- und Max-Tarife)", "✅ Du willst Zugriff auf mehrere Modelle — GPT-5, Claude und Gemini in einem Suchwerkzeug", "✅ Du brauchst eine universelle KI-Suchmaschine für alltägliche Recherchefragen"]', faq='[{"q": "Was ist Consensus AI?", "a": "Consensus ist eine KI-gestützte akademische Suchmaschine, die über 200 Mio. peer-reviewte Studien durchsucht. Deep Search und Research Agent extrahieren zentrale Erkenntnisse, zeigen Konsens-Prozentwerte über Studien hinweg und liefern zitierte Antworten — speziell für wissenschaftliche und medizinische Fragen."}, {"q": "Ist Consensus kostenlos?", "a": "Ja. Der kostenlose Tarif umfasst die einfache Quick Search, Abstract-Zusammenfassungen, begrenzte Pro-Nachrichten und etwa 3 Deep Searches pro Monat. Consensus Pro kostet $10/Monat, und Studierende erhalten Pro für $9/Monat mit .edu/.ac-Verifizierung."}, {"q": "Ist Perplexity gut für die akademische Recherche?", "a": "Perplexity durchsucht das Web inklusive akademischer Quellen, spezialisiert sich aber nicht so auf peer-reviewte Studien wie Consensus. Für akademische Recherche mit Studienzitaten und Evidenzqualität ist Consensus zuverlässiger. Perplexity ist besser für breite Recherche und aktuelle Ereignisse."}, {"q": "Was kostet Perplexity?", "a": "Perplexity Free ist $0 mit etwa 5 Pro-Suchen pro Tag. Perplexity Pro kostet $20/Monat oder $200/Jahr und umfasst rund 20 Deep-Research-Läufe pro Tag; Max kostet $200/Monat oder $2000/Jahr. Deep Research läuft bei Pro und Max auf Claude Opus 4.5/4.6."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Вам потрібні відповіді, підкріплені рецензованими науковими статтями, а не просто вебсторінками", "✅ Ви дослідник, студент або медичний фахівець, якому потрібні цитовані академічні джерела", "✅ Вам потрібен індикатор консенсусу, що показує, який відсоток досліджень погоджується з твердженням", "✅ Ви працюєте в медицині, науці чи політиці, де якість доказів має найбільше значення", "✅ Вам потрібен Deep Search по 200+ млн статей за низькою ціною — Pro $10/міс, для студентів $9/міс"]', choose_b='["✅ Вам потрібні швидкі відповіді з усього інтернету, а не лише з академічних баз", "✅ Вам потрібні свіжі новини, останні події або інформація, оновлена за кілька днів", "✅ Вам потрібен агентний Deep Research на базі Claude Opus 4.5/4.6 (плани Pro та Max)", "✅ Вам потрібен доступ до кількох моделей — GPT-5, Claude і Gemini в одному пошуковому інструменті", "✅ Вам потрібна універсальна ШІ-пошукова система для щоденних дослідницьких запитів"]', faq='[{"q": "Що таке Consensus AI?", "a": "Consensus — це академічна пошукова система на базі ШІ, яка шукає по понад 200 млн рецензованих статей. Deep Search та Research Agent видобувають ключові висновки, показують відсоток консенсусу між дослідженнями й дають відповіді з посиланнями — саме для наукових і медичних запитань."}, {"q": "Чи Consensus безкоштовний?", "a": "Так. Безкоштовний план включає базовий Quick Search, стислі виклади анотацій, обмежену кількість Pro-повідомлень і близько 3 Deep Search на місяць. Consensus Pro коштує $10/міс, а студенти можуть отримати Pro за $9/міс із підтвердженням .edu/.ac."}, {"q": "Чи підходить Perplexity для академічних досліджень?", "a": "Perplexity шукає в інтернеті, включно з академічними джерелами, але не спеціалізується на рецензованих статтях так, як Consensus. Для академічних досліджень, що потребують цитування праць та оцінки якості доказів, Consensus надійніший. Perplexity кращий для широких досліджень і свіжих новин."}, {"q": "Скільки коштує Perplexity?", "a": "Perplexity Free — $0 з приблизно 5 Pro-пошуками на день. Perplexity Pro коштує $20/міс або $200/рік і включає близько 20 запусків Deep Research на день; Max — $200/міс або $2000/рік. Deep Research працює на Claude Opus 4.5/4.6 для планів Pro та Max."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם צריכים תשובות מגובות במאמרים מדעיים שעברו ביקורת עמיתים — לא רק דפי אינטרנט", "✅ אתם חוקרים, סטודנטים או אנשי מקצוע בתחום הבריאות הזקוקים למקורות אקדמיים מצוטטים", "✅ אתם רוצים מדדי קונצנזוס שמראים איזה אחוז מהמחקרים מסכים עם טענה", "✅ אתם עובדים ברפואה, במדע או במדיניות, שם איכות הראיות חשובה מכול", "✅ אתם רוצים Deep Search על פני 200+ מיליון מאמרים במחיר נמוך — Pro ב-$10 לחודש, סטודנט ב-$9 לחודש"]', choose_b='["✅ אתם רוצים תשובות מהירות מכל רחבי הרשת, לא רק ממאגרים אקדמיים", "✅ אתם צריכים חדשות עדכניות, אירועים אחרונים או מידע שהתעדכן בתוך ימים", "✅ אתם רוצים Deep Research אג''נטי המופעל על ידי Claude Opus 4.5/4.6 (תוכניות Pro ו-Max)", "✅ אתם רוצים גישה למספר מודלים — GPT-5, Claude ו-Gemini בכלי חיפוש אחד", "✅ אתם צריכים מנוע חיפוש AI כללי לשאלות מחקר יומיומיות"]', faq='[{"q": "מהו Consensus AI?", "a": "Consensus הוא מנוע חיפוש אקדמי מבוסס AI שסורק למעלה מ-200 מיליון מאמרים שעברו ביקורת עמיתים. ה-Deep Search וה-Research Agent מחלצים ממצאים מרכזיים, מציגים אחוזי קונצנזוס בין מחקרים ומספקים תשובות מצוטטות — במיוחד לשאלות מדעיות ורפואיות."}, {"q": "האם Consensus חינמי?", "a": "כן. התוכנית החינמית כוללת Quick Search בסיסי, סיכומי תקצירים, מספר מוגבל של הודעות Pro וכ-3 חיפושי Deep Search בחודש. Consensus Pro עולה $10 לחודש, וסטודנטים יכולים לקבל Pro ב-$9 לחודש עם אימות .edu/.ac."}, {"q": "האם Perplexity טוב למחקר אקדמי?", "a": "Perplexity סורק את הרשת כולל מקורות אקדמיים, אך אינו מתמחה במאמרים שעברו ביקורת עמיתים כמו Consensus. למחקר אקדמי הדורש ציטוטי מחקרים ואיכות ראיות, Consensus אמין יותר. Perplexity טוב יותר למחקר רחב ולחדשות עדכניות."}, {"q": "כמה עולה Perplexity?", "a": "Perplexity Free הוא $0 עם כ-5 חיפושי Pro ביום. Perplexity Pro עולה $20 לחודש או $200 לשנה וכולל כ-20 הרצות Deep Research ביום; Max עולה $200 לחודש או $2000 לשנה. Deep Research פועל על Claude Opus 4.5/4.6 בתוכניות Pro ו-Max."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous voulez des réponses appuyées par des articles scientifiques évalués par des pairs — pas seulement des pages web", "✅ Vous êtes chercheur, étudiant ou professionnel de santé et avez besoin de sources académiques citées", "✅ Vous voulez des indicateurs de consensus montrant quel pourcentage d''études s''accorde sur une affirmation", "✅ Vous travaillez en médecine, en science ou dans les politiques publiques, où la qualité des preuves prime", "✅ Vous voulez Deep Search sur plus de 200 millions d''articles à bas prix — Pro à 10 $/mois, Étudiant à 9 $/mois"]', choose_b='["✅ Vous voulez des réponses rapides tirées de tout le web, pas seulement de bases académiques", "✅ Vous avez besoin d''actualités récentes, d''événements récents ou d''informations mises à jour en quelques jours", "✅ Vous voulez une Deep Research agentique propulsée par Claude Opus 4.5/4.6 (offres Pro et Max)", "✅ Vous voulez un accès multi-modèles — GPT-5, Claude et Gemini dans un seul outil de recherche", "✅ Vous avez besoin d''un moteur de recherche IA polyvalent pour vos questions de recherche quotidiennes"]', faq='[{"q": "Qu''est-ce que Consensus AI ?", "a": "Consensus est un moteur de recherche académique par IA qui explore plus de 200 millions d''articles évalués par des pairs. Ses fonctions Deep Search et Research Agent extraient les conclusions clés, affichent des pourcentages de consensus entre études et fournissent des réponses citées — spécifiquement pour les questions scientifiques et médicales."}, {"q": "Consensus est-il gratuit ?", "a": "Oui. L''offre gratuite comprend la recherche Quick Search de base, des résumés d''abstracts, un nombre limité de messages Pro et environ 3 Deep Searches par mois. Consensus Pro coûte 10 $/mois, et les étudiants peuvent obtenir Pro à 9 $/mois avec une vérification .edu/.ac."}, {"q": "Perplexity est-il bon pour la recherche académique ?", "a": "Perplexity explore le web, y compris des sources académiques, mais ne se spécialise pas dans les articles évalués par des pairs comme le fait Consensus. Pour la recherche académique nécessitant des citations d''études et une qualité de preuves, Consensus est plus fiable. Perplexity convient mieux à la recherche large et à l''actualité."}, {"q": "Combien coûte Perplexity ?", "a": "Perplexity Free est à 0 $ avec environ 5 recherches Pro par jour. Perplexity Pro coûte 20 $/mois ou 200 $/an et inclut environ 20 Deep Research par jour ; Max coûte 200 $/mois ou 2000 $/an. Deep Research fonctionne avec Claude Opus 4.5/4.6 pour les offres Pro et Max."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você precisa de respostas embasadas em artigos científicos revisados por pares — não apenas páginas web", "✅ Você é pesquisador, estudante ou profissional de saúde que precisa de fontes acadêmicas citadas", "✅ Você quer medidores de consenso que mostram qual porcentagem de estudos concorda com uma afirmação", "✅ Você trabalha em medicina, ciência ou políticas públicas, onde a qualidade das evidências importa mais", "✅ Você quer Deep Search em mais de 200 milhões de artigos a baixo custo — Pro a US$10/mês, Estudante a US$9/mês"]', choose_b='["✅ Você quer respostas rápidas de toda a web, não apenas de bases acadêmicas", "✅ Você precisa de notícias atuais, eventos recentes ou informações atualizadas em poucos dias", "✅ Você quer Deep Research agêntico com tecnologia Claude Opus 4.5/4.6 (planos Pro e Max)", "✅ Você quer acesso a vários modelos — GPT-5, Claude e Gemini em uma única ferramenta de busca", "✅ Você precisa de um buscador de IA de uso geral para perguntas de pesquisa do dia a dia"]', faq='[{"q": "O que é o Consensus AI?", "a": "O Consensus é um buscador acadêmico com IA que pesquisa mais de 200 milhões de artigos revisados por pares. Seu Deep Search e Research Agent extraem descobertas-chave, mostram porcentagens de consenso entre estudos e fornecem respostas com citações — especificamente para perguntas científicas e médicas."}, {"q": "O Consensus é gratuito?", "a": "Sim. O plano gratuito inclui o Quick Search básico, resumos de abstracts, mensagens Pro limitadas e cerca de 3 Deep Searches por mês. O Consensus Pro custa US$10/mês, e estudantes podem obter o Pro por US$9/mês com verificação .edu/.ac."}, {"q": "O Perplexity é bom para pesquisa acadêmica?", "a": "O Perplexity pesquisa a web, incluindo fontes acadêmicas, mas não se especializa em artigos revisados por pares como o Consensus. Para pesquisa acadêmica que exige citações de estudos e qualidade de evidências, o Consensus é mais confiável. O Perplexity é melhor para pesquisa ampla e eventos atuais."}, {"q": "Quanto custa o Perplexity?", "a": "O Perplexity Free é US$0 com cerca de 5 buscas Pro por dia. O Perplexity Pro custa US$20/mês ou US$200/ano e inclui cerca de 20 execuções de Deep Research por dia; o Max custa US$200/mês ou US$2000/ano. O Deep Research roda em Claude Opus 4.5/4.6 nos planos Pro e Max."}]'::jsonb WHERE slug='consensus-vs-perplexity' AND lang='pt';

-- duolingo-max-vs-khanmigo
UPDATE comparisons SET choose_a='["✅ You''re learning a new language and want AI conversation practice like Video Call with Lily and Roleplay, powered by GPT-4o", "✅ You love gamified learning — streaks, XP, leagues — to stay motivated every day", "✅ You want realtime spoken practice with an AI character in true-to-life scenarios", "✅ You''re a casual learner who wants bite-sized lessons on mobile anytime"]', choose_b='["✅ You''re a student needing help with math, science, history, or the humanities", "✅ You want a Socratic tutor that guides you to the answer instead of just handing it over", "✅ You''re a teacher wanting AI help with lesson planning, feedback, and student support — free in 44+ countries thanks to Microsoft", "✅ You study with Khan Academy and want AI built into that curriculum"]', faq='[{"q": "What is Duolingo Max?", "a": "Duolingo Max is Duolingo''s top subscription tier, adding AI features powered by GPT-4o. Its flagship feature is Video Call — a realtime spoken conversation with the AI character Lily — alongside Roleplay, where you practice real-life dialogues with AI characters. It costs $167.99/year or $29.99/month."}, {"q": "What is Khanmigo?", "a": "Khanmigo is Khan Academy''s AI tutor, built on GPT-4 (with GPT-4o multimodal integration in progress). It helps students across academic subjects using the Socratic method — asking guiding questions rather than giving direct answers — and is tied to Khan Academy''s curriculum."}, {"q": "Is Khanmigo free?", "a": "Khanmigo is free for teachers in 44+ countries, supported by Microsoft. For learners and parents/families it costs $4/month or $44/year (the annual plan saves roughly two months). A parent account can add up to 10 children."}, {"q": "How much does Duolingo cost?", "a": "Duolingo has a free tier at $0. Super is $95.99/year, Duolingo Max is $167.99/year or $29.99/month, and Super Family starts at $119.99/year for up to 6 people. Only Max includes the GPT-4o AI features like Video Call and Roleplay."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='en';
UPDATE comparisons SET choose_a='["✅ Вы учите новый язык и хотите практику разговора с ИИ — Видеозвонок с Лили и Ролевые сценарии на базе GPT-4o", "✅ Вам нравится геймификация — стрики, XP, лиги — чтобы заниматься каждый день", "✅ Вам нужна живая устная практика с ИИ-персонажем в реалистичных ситуациях", "✅ Вы учитесь для себя и хотите короткие уроки в мобильном в любое время"]', choose_b='["✅ Вы школьник или студент, которому нужна помощь по математике, естественным наукам, истории или гуманитарным предметам", "✅ Вам нужен репетитор по методу Сократа, который наводит на ответ, а не выдаёт его сразу", "✅ Вы преподаватель и хотите ИИ-помощь в планировании уроков, обратной связи и поддержке учеников — бесплатно в 44+ странах благодаря Microsoft", "✅ Вы занимаетесь на Khan Academy и хотите ИИ, встроенный прямо в эту программу"]', faq='[{"q": "Что такое Duolingo Max?", "a": "Duolingo Max — это высший уровень подписки Duolingo с ИИ-функциями на базе GPT-4o. Главная функция — Видеозвонок: живой устный разговор с ИИ-персонажем Лили, а также Ролевые сценарии, где вы отрабатываете реальные диалоги с ИИ-персонажами. Стоит $167.99 в год или $29.99 в месяц."}, {"q": "Что такое Khanmigo?", "a": "Khanmigo — это ИИ-репетитор от Khan Academy на базе GPT-4 (интеграция мультимодального GPT-4o в процессе). Он помогает по академическим предметам по методу Сократа — задаёт наводящие вопросы, а не выдаёт готовый ответ — и связан с учебной программой Khan Academy."}, {"q": "Khanmigo бесплатный?", "a": "Khanmigo бесплатен для учителей в 44+ странах при поддержке Microsoft. Для учащихся и родителей/семей он стоит $4 в месяц или $44 в год (годовой план экономит примерно два месяца). К родительскому аккаунту можно добавить до 10 детей."}, {"q": "Сколько стоит Duolingo?", "a": "У Duolingo есть бесплатный уровень за $0. Super стоит $95.99 в год, Duolingo Max — $167.99 в год или $29.99 в месяц, а Super Family — от $119.99 в год на 6 человек. ИИ-функции на GPT-4o, такие как Видеозвонок и Ролевые сценарии, есть только в Max."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='ru';
UPDATE comparisons SET choose_a='["✅ Estás aprendiendo un idioma nuevo y quieres práctica de conversación con IA, como Videollamada con Lily y Roleplay, con GPT-4o", "✅ Te encanta el aprendizaje gamificado — rachas, XP, ligas — para mantener la motivación cada día", "✅ Quieres práctica oral en tiempo real con un personaje de IA en escenarios realistas", "✅ Eres un aprendiz casual que quiere lecciones cortas en el móvil en cualquier momento"]', choose_b='["✅ Eres estudiante y necesitas ayuda con matemáticas, ciencias, historia o humanidades", "✅ Quieres un tutor socrático que te guíe hacia la respuesta en lugar de dártela directamente", "✅ Eres docente y quieres ayuda de IA para planificar clases, dar feedback y apoyar a los alumnos — gratis en más de 44 países gracias a Microsoft", "✅ Estudias con Khan Academy y quieres IA integrada en ese currículo"]', faq='[{"q": "¿Qué es Duolingo Max?", "a": "Duolingo Max es el nivel de suscripción más alto de Duolingo, con funciones de IA impulsadas por GPT-4o. Su función estrella es Videollamada — una conversación oral en tiempo real con el personaje de IA Lily — junto con Roleplay, donde practicas diálogos de la vida real con personajes de IA. Cuesta 167,99 $/año o 29,99 $/mes."}, {"q": "¿Qué es Khanmigo?", "a": "Khanmigo es el tutor de IA de Khan Academy, basado en GPT-4 (con la integración multimodal de GPT-4o en curso). Ayuda a los estudiantes en materias académicas con el método socrático — hace preguntas guía en vez de dar la respuesta directa — y está vinculado al currículo de Khan Academy."}, {"q": "¿Khanmigo es gratis?", "a": "Khanmigo es gratis para docentes en más de 44 países, con el apoyo de Microsoft. Para estudiantes y familias cuesta 4 $/mes o 44 $/año (el plan anual ahorra unos dos meses). Una cuenta de padre o madre puede añadir hasta 10 hijos."}, {"q": "¿Cuánto cuesta Duolingo?", "a": "Duolingo tiene un nivel gratuito de 0 $. Super cuesta 95,99 $/año, Duolingo Max cuesta 167,99 $/año o 29,99 $/mes, y Super Family desde 119,99 $/año para hasta 6 personas. Solo Max incluye las funciones de IA con GPT-4o como Videollamada y Roleplay."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='es';
UPDATE comparisons SET choose_a='["✅ Du lernst eine neue Sprache und möchtest KI-Konversationstraining wie Videoanruf mit Lily und Roleplay, angetrieben von GPT-4o", "✅ Du liebst spielerisches Lernen — Streaks, XP, Ligen — um jeden Tag motiviert zu bleiben", "✅ Du willst gesprochenes Echtzeit-Training mit einer KI-Figur in realistischen Szenarien", "✅ Du lernst nebenbei und möchtest jederzeit kurze Lektionen auf dem Handy"]', choose_b='["✅ Du bist Schüler oder Student und brauchst Hilfe in Mathe, Naturwissenschaften, Geschichte oder Geisteswissenschaften", "✅ Du willst einen sokratischen Tutor, der dich zur Antwort führt, statt sie direkt zu verraten", "✅ Du bist Lehrkraft und möchtest KI-Hilfe bei Unterrichtsplanung, Feedback und Schülerbetreuung — kostenlos in über 44 Ländern dank Microsoft", "✅ Du lernst mit Khan Academy und willst KI direkt in diesem Lehrplan"]', faq='[{"q": "Was ist Duolingo Max?", "a": "Duolingo Max ist die höchste Abostufe von Duolingo mit KI-Funktionen auf Basis von GPT-4o. Die Hauptfunktion ist Videoanruf — ein gesprochenes Echtzeit-Gespräch mit der KI-Figur Lily — zusammen mit Roleplay, wo du Alltagsdialoge mit KI-Figuren übst. Es kostet 167,99 $/Jahr oder 29,99 $/Monat."}, {"q": "Was ist Khanmigo?", "a": "Khanmigo ist der KI-Tutor der Khan Academy auf Basis von GPT-4 (die multimodale GPT-4o-Integration ist in Arbeit). Er hilft in akademischen Fächern nach der sokratischen Methode — er stellt leitende Fragen, statt die Antwort direkt zu geben — und ist an den Lehrplan der Khan Academy gekoppelt."}, {"q": "Ist Khanmigo kostenlos?", "a": "Khanmigo ist für Lehrkräfte in über 44 Ländern kostenlos, unterstützt von Microsoft. Für Lernende und Eltern/Familien kostet es 4 $/Monat oder 44 $/Jahr (das Jahresabo spart rund zwei Monate). Ein Elternkonto kann bis zu 10 Kinder hinzufügen."}, {"q": "Was kostet Duolingo?", "a": "Duolingo hat eine kostenlose Stufe für 0 $. Super kostet 95,99 $/Jahr, Duolingo Max 167,99 $/Jahr oder 29,99 $/Monat und Super Family ab 119,99 $/Jahr für bis zu 6 Personen. Nur Max enthält die KI-Funktionen mit GPT-4o wie Videoanruf und Roleplay."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='de';
UPDATE comparisons SET choose_a='["✅ Ви вивчаєте нову мову й хочете практику розмови з ШІ — Відеодзвінок із Лілі та Рольові сценарії на основі GPT-4o", "✅ Вам подобається гейміфікація — стріки, XP, ліги — щоб займатися щодня", "✅ Вам потрібна жива усна практика з ШІ-персонажем у реалістичних ситуаціях", "✅ Ви навчаєтеся для себе й хочете короткі уроки в мобільному будь-коли"]', choose_b='["✅ Ви учень чи студент, якому потрібна допомога з математики, природничих наук, історії чи гуманітарних предметів", "✅ Вам потрібен репетитор за методом Сократа, який підводить до відповіді, а не видає її одразу", "✅ Ви викладач і хочете ШІ-допомогу з плануванням уроків, зворотним зв''язком і підтримкою учнів — безкоштовно в 44+ країнах завдяки Microsoft", "✅ Ви навчаєтеся на Khan Academy й хочете ШІ, вбудований у цю програму"]', faq='[{"q": "Що таке Duolingo Max?", "a": "Duolingo Max — це найвищий рівень підписки Duolingo з ШІ-функціями на основі GPT-4o. Головна функція — Відеодзвінок: жива усна розмова з ШІ-персонажем Лілі, а також Рольові сценарії, де ви відпрацьовуєте реальні діалоги з ШІ-персонажами. Коштує $167.99 на рік або $29.99 на місяць."}, {"q": "Що таке Khanmigo?", "a": "Khanmigo — це ШІ-репетитор від Khan Academy на основі GPT-4 (інтеграція мультимодального GPT-4o триває). Він допомагає з академічними предметами за методом Сократа — ставить навідні запитання, а не видає готову відповідь — і пов''язаний із навчальною програмою Khan Academy."}, {"q": "Khanmigo безкоштовний?", "a": "Khanmigo безкоштовний для вчителів у 44+ країнах за підтримки Microsoft. Для учнів і батьків/родин він коштує $4 на місяць або $44 на рік (річний план економить близько двох місяців). До батьківського акаунта можна додати до 10 дітей."}, {"q": "Скільки коштує Duolingo?", "a": "У Duolingo є безкоштовний рівень за $0. Super коштує $95.99 на рік, Duolingo Max — $167.99 на рік або $29.99 на місяць, а Super Family — від $119.99 на рік на 6 осіб. ШІ-функції на GPT-4o, як-от Відеодзвінок і Рольові сценарії, є лише в Max."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='ua';
UPDATE comparisons SET choose_a='["✅ אתם לומדים שפה חדשה ורוצים תרגול שיחה עם בינה מלאכותית — שיחת וידאו עם לילי ותרחישי Roleplay מבוססי GPT-4o", "✅ אתם אוהבים למידה משחקית — רצפים, XP, ליגות — כדי להישאר מוטיבציוניים כל יום", "✅ אתם רוצים תרגול דיבור בזמן אמת עם דמות בינה מלאכותית בתרחישים מהחיים", "✅ אתם לומדים בקצב חופשי ורוצים שיעורים קצרים בנייד בכל זמן"]', choose_b='["✅ אתם תלמידים או סטודנטים שזקוקים לעזרה במתמטיקה, מדעים, היסטוריה או מדעי הרוח", "✅ אתם רוצים מורה בשיטה הסוקרטית שמכוון אתכם לתשובה במקום לתת אותה ישירות", "✅ אתם מורים ורוצים עזרת בינה מלאכותית בתכנון שיעורים, משוב ותמיכה בתלמידים — חינם ביותר מ-44 מדינות בזכות Microsoft", "✅ אתם לומדים ב-Khan Academy ורוצים בינה מלאכותית משולבת בתוכנית הלימודים הזו"]', faq='[{"q": "מה זה Duolingo Max?", "a": "Duolingo Max הוא רמת המנוי הגבוהה ביותר של Duolingo, עם יכולות בינה מלאכותית מבוססות GPT-4o. הפיצ''ר המוביל הוא שיחת וידאו — שיחה קולית בזמן אמת עם דמות הבינה המלאכותית לילי — לצד Roleplay, שבו מתרגלים דיאלוגים מהחיים עם דמויות בינה מלאכותית. המחיר הוא 167.99$ לשנה או 29.99$ לחודש."}, {"q": "מה זה Khanmigo?", "a": "Khanmigo הוא מורה הבינה המלאכותית של Khan Academy, מבוסס GPT-4 (שילוב GPT-4o הרב-מודלי בתהליך). הוא עוזר לתלמידים במקצועות אקדמיים בשיטה הסוקרטית — שואל שאלות מכוונות במקום לתת תשובה ישירה — ומקושר לתוכנית הלימודים של Khan Academy."}, {"q": "האם Khanmigo חינמי?", "a": "Khanmigo חינמי למורים ביותר מ-44 מדינות, בתמיכת Microsoft. עבור לומדים והורים/משפחות המחיר הוא 4$ לחודש או 44$ לשנה (התוכנית השנתית חוסכת כחודשיים). חשבון הורה יכול להוסיף עד 10 ילדים."}, {"q": "כמה עולה Duolingo?", "a": "ל-Duolingo יש רמה חינמית ב-0$. Super עולה 95.99$ לשנה, Duolingo Max עולה 167.99$ לשנה או 29.99$ לחודש, ו-Super Family מתחיל מ-119.99$ לשנה עד 6 אנשים. רק Max כולל את יכולות הבינה המלאכותית מבוססות GPT-4o כמו שיחת וידאו ו-Roleplay."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='he';
UPDATE comparisons SET choose_a='["✅ Vous apprenez une nouvelle langue et voulez de la pratique conversationnelle avec l''IA, comme l''Appel vidéo avec Lily et le Roleplay, propulsés par GPT-4o", "✅ Vous aimez l''apprentissage ludique — séries, XP, ligues — pour rester motivé chaque jour", "✅ Vous voulez une pratique orale en temps réel avec un personnage IA dans des scénarios réalistes", "✅ Vous êtes un apprenant occasionnel qui veut des leçons courtes sur mobile à tout moment"]', choose_b='["✅ Vous êtes élève ou étudiant et avez besoin d''aide en maths, sciences, histoire ou lettres", "✅ Vous voulez un tuteur socratique qui vous guide vers la réponse au lieu de la donner directement", "✅ Vous êtes enseignant et voulez l''aide de l''IA pour préparer vos cours, donner du feedback et soutenir les élèves — gratuit dans plus de 44 pays grâce à Microsoft", "✅ Vous étudiez avec Khan Academy et voulez une IA intégrée à ce programme"]', faq='[{"q": "Qu''est-ce que Duolingo Max ?", "a": "Duolingo Max est le niveau d''abonnement le plus élevé de Duolingo, avec des fonctions d''IA propulsées par GPT-4o. Sa fonction phare est l''Appel vidéo — une conversation orale en temps réel avec le personnage IA Lily — accompagnée du Roleplay, où vous pratiquez des dialogues de la vie réelle avec des personnages IA. Il coûte 167,99 $/an ou 29,99 $/mois."}, {"q": "Qu''est-ce que Khanmigo ?", "a": "Khanmigo est le tuteur IA de Khan Academy, basé sur GPT-4 (l''intégration multimodale de GPT-4o est en cours). Il aide les élèves dans les matières académiques selon la méthode socratique — il pose des questions qui guident plutôt que de donner la réponse directe — et il est lié au programme de Khan Academy."}, {"q": "Khanmigo est-il gratuit ?", "a": "Khanmigo est gratuit pour les enseignants dans plus de 44 pays, avec le soutien de Microsoft. Pour les apprenants et les parents/familles, il coûte 4 $/mois ou 44 $/an (l''offre annuelle économise environ deux mois). Un compte parent peut ajouter jusqu''à 10 enfants."}, {"q": "Combien coûte Duolingo ?", "a": "Duolingo propose un niveau gratuit à 0 $. Super coûte 95,99 $/an, Duolingo Max 167,99 $/an ou 29,99 $/mois, et Super Family à partir de 119,99 $/an pour jusqu''à 6 personnes. Seul Max inclut les fonctions d''IA sous GPT-4o comme l''Appel vidéo et le Roleplay."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='fr';
UPDATE comparisons SET choose_a='["✅ Você está aprendendo um novo idioma e quer prática de conversa com IA, como Videochamada com a Lily e Roleplay, com GPT-4o", "✅ Você adora aprendizado gamificado — sequências, XP, ligas — para manter a motivação todos os dias", "✅ Você quer prática oral em tempo real com um personagem de IA em cenários realistas", "✅ Você é um estudante casual que quer lições curtas no celular a qualquer hora"]', choose_b='["✅ Você é estudante e precisa de ajuda com matemática, ciências, história ou humanidades", "✅ Você quer um tutor socrático que o guie até a resposta em vez de entregá-la diretamente", "✅ Você é professor e quer ajuda de IA no planejamento de aulas, feedback e apoio aos alunos — grátis em mais de 44 países graças à Microsoft", "✅ Você estuda na Khan Academy e quer IA integrada a esse currículo"]', faq='[{"q": "O que é o Duolingo Max?", "a": "O Duolingo Max é o nível de assinatura mais alto do Duolingo, com recursos de IA baseados no GPT-4o. Seu recurso principal é a Videochamada — uma conversa falada em tempo real com a personagem de IA Lily — junto com o Roleplay, onde você pratica diálogos da vida real com personagens de IA. Custa US$ 167,99/ano ou US$ 29,99/mês."}, {"q": "O que é o Khanmigo?", "a": "O Khanmigo é o tutor de IA da Khan Academy, baseado no GPT-4 (com a integração multimodal do GPT-4o em andamento). Ele ajuda os estudantes em matérias acadêmicas pelo método socrático — faz perguntas que orientam em vez de dar a resposta direta — e é ligado ao currículo da Khan Academy."}, {"q": "O Khanmigo é gratuito?", "a": "O Khanmigo é gratuito para professores em mais de 44 países, com apoio da Microsoft. Para alunos e pais/famílias custa US$ 4/mês ou US$ 44/ano (o plano anual economiza cerca de dois meses). Uma conta de responsável pode adicionar até 10 crianças."}, {"q": "Quanto custa o Duolingo?", "a": "O Duolingo tem um nível gratuito de US$ 0. O Super custa US$ 95,99/ano, o Duolingo Max custa US$ 167,99/ano ou US$ 29,99/mês, e o Super Family a partir de US$ 119,99/ano para até 6 pessoas. Só o Max inclui os recursos de IA com GPT-4o, como Videochamada e Roleplay."}]'::jsonb WHERE slug='duolingo-max-vs-khanmigo' AND lang='pt';
